// PM2 process manifest for production. aaPanel's "PM2 Manager"
// (or `pm2 start ecosystem.config.js` from the repo root) reads
// this and supervises both apps. Assumes:
//
//   - Both apps already have their dependencies installed
//     (`npm ci` inside backend/ and frontend/)
//   - The backend has been compiled (`npm run build` -> dist/)
//   - The frontend has been built (`npm run build` -> .next/)
//   - Real env vars come from the host (aaPanel "Environment
//     Variables" tab, or .env files placed inside each app dir)
//
// Don't commit real secrets here.

module.exports = {
  apps: [
    {
      name: 'lucifer-api',
      cwd: './backend',
      // Apply pending Prisma migrations on boot, then hand off to the
      // compiled Nest entry. `npx --no-install` skips fetching since
      // prisma is already a local dep.
      script: 'sh',
      args: '-c "npx --no-install prisma migrate deploy && node dist/main.js"',
      instances: 1,
      exec_mode: 'fork',
      autorestart: true,
      watch: false,
      max_memory_restart: '512M',
      env: {
        NODE_ENV: 'production',
      },
    },
    {
      name: 'lucifer-web',
      cwd: './frontend',
      // Plain `next start` — Next 16 reads .next/ for the production
      // build and serves on $PORT (default 3000).
      script: 'npm',
      args: 'run start',
      instances: 1,
      exec_mode: 'fork',
      autorestart: true,
      watch: false,
      max_memory_restart: '512M',
      env: {
        NODE_ENV: 'production',
      },
    },
  ],
};
